def longest_diverse_string(a: int, b: int, c: int) -> str:
    heap = [(-count, ch) for count, ch in ((a, "a"), (b, "b"), (c, "c")) if count]
    heapq.heapify(heap)
    out = []
    while heap:
        count, ch = heapq.heappop(heap)
        if len(out) >= 2 and out[-1] == out[-2] == ch:
            if not heap:
                break                      # only the blocked letter remains
            count2, ch2 = heapq.heappop(heap)
            out.append(ch2)                # use the runner up as a separator
            if count2 + 1:
                heapq.heappush(heap, (count2 + 1, ch2))
            heapq.heappush(heap, (count, ch))
        else:
            out.append(ch)
            if count + 1:
                heapq.heappush(heap, (count + 1, ch))
    return "".join(out)

class RangeModule:
    def __init__(self):
        # Sorted boundaries: [b[0], b[1]), [b[2], b[3]), ... are tracked.
        self.b = []

    def addRange(self, left: int, right: int) -> None:
        i = bisect.bisect_left(self.b, left)
        j = bisect.bisect_right(self.b, right)
        patch = []
        if i % 2 == 0:
            patch.append(left)     # left lies outside: it opens an interval
        if j % 2 == 0:
            patch.append(right)    # right lies outside: it closes the interval
        self.b[i:j] = patch

    def queryRange(self, left: int, right: int) -> bool:
        i = bisect.bisect_right(self.b, left)
        j = bisect.bisect_left(self.b, right)
        # No boundary strictly inside and the range sits inside an interval.
        return i == j and i % 2 == 1

    def removeRange(self, left: int, right: int) -> None:
        i = bisect.bisect_left(self.b, left)
        j = bisect.bisect_right(self.b, right)
        patch = []
        if i % 2 == 1:
            patch.append(left)     # left lies inside: close that interval here
        if j % 2 == 1:
            patch.append(right)    # right lies inside: reopen after the gap
        self.b[i:j] = patch

