def min_swaps(nums: list[int]) -> int:
    n = len(nums)
    ones = sum(nums)
    if ones in (0, n):
        return 0
    window = sum(nums[:ones])          # ones inside the first window
    best = window
    for start in range(1, n):
        # Slide by one: drop nums[start - 1], add the element entering at the far end.
        window += nums[(start + ones - 1) % n] - nums[start - 1]
        if window > best:
            best = window
    return ones - best                 # zeros left in the best window

class MyStack:
    def __init__(self):
        self.q = deque()   # front of the queue is the top of the stack

    def push(self, x: int) -> None:
        self.q.append(x)
        # Rotate the older elements behind x so x reaches the front.
        for _ in range(len(self.q) - 1):
            self.q.append(self.q.popleft())

    def pop(self) -> int:
        return self.q.popleft()

    def top(self) -> int:
        return self.q[0]

    def empty(self) -> bool:
        return len(self.q) == 0

