def calculate_tax(brackets: list[list[int]], income: int) -> float:
    tax = 0.0
    prev = 0                              # upper bound of the previous bracket
    for upper, percent in brackets:
        if income <= prev:
            break
        taxed = min(income, upper) - prev  # part of income inside this bracket
        tax += taxed * percent / 100
        prev = upper
    return tax

def count_fair_pairs(nums: list[int], lower: int, upper: int) -> int:
    a = sorted(nums)

    def at_most(t: int) -> int:
        # Number of pairs i < j with a[i] + a[j] <= t.
        count, i, j = 0, 0, len(a) - 1
        while i < j:
            if a[i] + a[j] <= t:
                count += j - i   # a[i] pairs with every a[i+1..j]
                i += 1
            else:
                j -= 1
        return count

    return at_most(upper) - at_most(lower - 1)

