def find_min_difference(time_points: list[str]) -> int:
    if len(time_points) > 1440:
        return 0                  # pigeonhole: some minute repeats
    seen = [False] * 1440
    for t in time_points:
        minute = int(t[:2]) * 60 + int(t[3:])
        if seen[minute]:
            return 0              # two identical times
        seen[minute] = True

    best = 1440
    first = prev = -1
    for minute in range(1440):
        if seen[minute]:
            if first < 0:
                first = minute
            else:
                best = min(best, minute - prev)
            prev = minute
    # Gap that wraps around midnight.
    return min(best, first + 1440 - prev)

