def invert_tree(root: Optional[TreeNode]) -> Optional[TreeNode]:
    stack = [root] if root else []
    while stack:
        node = stack.pop()
        node.left, node.right = node.right, node.left   # mirror this node
        if node.left:
            stack.append(node.left)
        if node.right:
            stack.append(node.right)
    return root

def max_freq(s: str, max_letters: int, min_size: int, max_size: int) -> int:
    k = min_size                     # longer substrings never do better
    letters = defaultdict(int)
    distinct = 0
    seen = defaultdict(int)
    for i, ch in enumerate(s):
        letters[ch] += 1
        if letters[ch] == 1:
            distinct += 1
        if i >= k:                   # drop the character leaving the window
            out = s[i - k]
            letters[out] -= 1
            if letters[out] == 0:
                distinct -= 1
        if i >= k - 1 and distinct <= max_letters:
            seen[s[i - k + 1:i + 1]] += 1
    return max(seen.values(), default=0)

