def reverse_parentheses(s: str) -> str:
    n = len(s)
    pair = [0] * n
    opens = []
    for i, ch in enumerate(s):          # match every parenthesis
        if ch == "(":
            opens.append(i)
        elif ch == ")":
            j = opens.pop()
            pair[i], pair[j] = j, i

    out = []
    i, step = 0, 1
    while i < n:
        if s[i] in "()":
            i = pair[i]                  # jump to the partner
            step = -step                 # and read the other way
        else:
            out.append(s[i])
        i += step
    return "".join(out)

def sub_array_ranges(nums: list[int]) -> int:
    def sum_of_maximums(a: list[int]) -> int:
        total, stack, n = 0, [], len(a)
        for i in range(n + 1):
            # The sentinel at i == n pops every remaining index.
            while stack and (i == n or a[stack[-1]] <= a[i]):
                mid = stack.pop()
                left = stack[-1] if stack else -1
                total += a[mid] * (mid - left) * (i - mid)
            stack.append(i)
        return total

