def find_length_of_shortest_subarray(arr: list[int]) -> int:
    n = len(arr)
    left = 0
    while left + 1 < n and arr[left] <= arr[left + 1]:
        left += 1
    if left == n - 1:
        return 0                       # already sorted
    right = n - 1
