            best = min(best, j - i - 1)  # drop arr[i+1 .. j-1]
            i += 1
        else:
            j += 1
    return best

def flat(arr: list, n: int) -> list:
    result = []
    # Each frame is an iterator over one list plus the depth of that list.
    stack = [(iter(arr), 0)]
    while stack:
        items, depth = stack[-1]
        for item in items:
            if isinstance(item, list) and depth < n:
                # Open this sublist; its items belong at depth + 1.
                stack.append((iter(item), depth + 1))
                break
            result.append(item)
        else:
            # The current list is exhausted; resume its parent.
            stack.pop()
    return result

