def find_redundant_connection(edges: list[list[int]]) -> list[int]:
    n = len(edges)
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x: int) -> int:
        # Path halving keeps the trees shallow.
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            return [a, b]          # this edge closes the only cycle
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
    return []

def find_content_children(g: list[int], s: list[int]) -> int:
    g = sorted(g)
    s = sorted(s)
    child = 0
    for cookie in s:
        if child == len(g):
            break
        # The smallest remaining cookie either fits the least greedy child or nobody.
        if cookie >= g[child]:
            child += 1
    return child

