def minimum_array_length(nums: list[int]) -> int:
    smallest = min(nums)
    # A remainder below the minimum would become a unique minimum that clears everything.
    for x in nums:
        if x % smallest != 0:
            return 1
    copies = nums.count(smallest)
    # Pairs of minimum values collapse into zeros that can never be used again.
    return (copies + 1) // 2

