def binary_gap(n: int) -> int:
    best = 0
    last_one = -1
    position = 0
    while n:
        if n & 1:
            if last_one >= 0:
                best = max(best, position - last_one)
            last_one = position
        n >>= 1
        position += 1
    return best

def invalid_transactions(transactions: list[str]) -> list[str]:
