def min_cost(grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])
    # Direction index d + 1 matches the sign value: right, left, down, up.
    moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    INF = float("inf")
    dist = [[INF] * n for _ in range(m)]
    dist[0][0] = 0
    dq = deque([(0, 0)])
    while dq:
        r, c = dq.popleft()
        d = dist[r][c]
        if r == m - 1 and c == n - 1:
            return d
        for k, (dr, dc) in enumerate(moves):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n:
                cost = 0 if grid[r][c] == k + 1 else 1
                if d + cost < dist[nr][nc]:
                    dist[nr][nc] = d + cost
                    # Free moves go to the front, paid moves to the back.
                    if cost == 0:
                        dq.appendleft((nr, nc))
                    else:
                        dq.append((nr, nc))
    return dist[m - 1][n - 1]

