def crawl(start_url: str, html_parser: "HtmlParser") -> List[str]:
    host = start_url.split("/")[2]       # "http:", "", hostname, path...
    seen = {start_url}
    queue = deque([start_url])
    while queue:
        url = queue.popleft()
        for link in html_parser.getUrls(url):
            # Stay on the starting hostname and fetch each page once.
            if link not in seen and link.split("/")[2] == host:
                seen.add(link)
                queue.append(link)
    return list(seen)

