def longest_subarray(nums: list[int]) -> int:
    left = 0
    zeros = 0
    best = 0
    for right, x in enumerate(nums):
        if x == 0:
            zeros += 1
        # Keep at most one zero inside the window.
        while zeros > 1:
            if nums[left] == 0:
                zeros -= 1
            left += 1
        best = max(best, right - left + 1)
    # One element of the best window is deleted.
    return best - 1

