def count_sub_islands(grid1: list[list[int]], grid2: list[list[int]]) -> int:
    m, n = len(grid2), len(grid2[0])
    land = [row[:] for row in grid2]      # working copy we can mark as visited
    count = 0
    for i in range(m):
        for j in range(n):
            if not land[i][j]:
                continue
            land[i][j] = 0
            stack = [(i, j)]
            inside = True
            while stack:
                r, c = stack.pop()
                if not grid1[r][c]:
                    inside = False        # keep filling so the island is consumed
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < m and 0 <= nc < n and land[nr][nc]:
                        land[nr][nc] = 0
                        stack.append((nr, nc))
            if inside:
                count += 1
    return count

def valid_tree(n: int, edges: list[list[int]]) -> bool:
    if len(edges) != n - 1:
        return False
    parent = list(range(n))
    size = [1] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            return False        # this edge closes a cycle
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
    return True

def minimum_effort_path(heights: list[list[int]]) -> int:
    rows, cols = len(heights), len(heights[0])
    best = [[float("inf")] * cols for _ in range(rows)]
    best[0][0] = 0
    heap = [(0, 0, 0)]                  # (effort so far, row, col)
    while heap:
        effort, r, c = heapq.heappop(heap)
        if effort > best[r][c]:
            continue                    # stale heap entry
        if r == rows - 1 and c == cols - 1:
            return effort
        h = heights[r][c]
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols:
                # A route's effort is its steepest step so far.
                cand = max(effort, abs(heights[nr][nc] - h))
                if cand < best[nr][nc]:
                    best[nr][nc] = cand
                    heapq.heappush(heap, (cand, nr, nc))
    return 0

