def generate_sentences(synonyms: list[list[str]], text: str) -> list[str]:
    parent = {}

    def find(x: str) -> str:
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in synonyms:
        parent[find(a)] = find(b)

    groups = defaultdict(list)
    for word in parent:
        groups[find(word)].append(word)
    for members in groups.values():
        members.sort()

    words = text.split(" ")
    options = [groups[find(w)] if w in parent else [w] for w in words]
    result, current = [], []

    def build(i: int) -> None:
        if i == len(options):
            result.append(" ".join(current))
            return
        for choice in options[i]:
            current.append(choice)
            build(i + 1)
            current.pop()

    build(0)
    return sorted(result)

def flatten(root: Optional[TreeNode]) -> None:
    cur = root
    while cur is not None:
        if cur.left is not None:
            # The rightmost node of the left subtree is last in its preorder.
            tail = cur.left
            while tail.right is not None:
                tail = tail.right
            tail.right = cur.right       # right subtree follows the left subtree
            cur.right = cur.left
            cur.left = None
        cur = cur.right

def shopping_offers(price: list[int], special: list[list[int]], needs: list[int]) -> int:
    n = len(price)
    # A bundle that is not cheaper than its contents can never help.
    offers = [o for o in special
              if sum(o[i] * price[i] for i in range(n)) > o[n]]

    @lru_cache(maxsize=None)
    def best(state: tuple) -> int:
        # Option 1: buy whatever is left at unit prices.
        cost = sum(q * p for q, p in zip(state, price))
        for o in offers:
            rest = tuple(state[i] - o[i] for i in range(n))
            if min(rest) >= 0:            # the bundle must not overshoot
                cost = min(cost, o[n] + best(rest))
        return cost

    return best(tuple(needs))

def check_perfect_number(num: int) -> bool:
    if num < 2:
        return False
    total = 1                      # 1 is a proper divisor of every num > 1
    d = 2
    while d * d <= num:
        if num % d == 0:
            total += d
            partner = num // d
            if partner != d:       # avoid counting a square root twice
                total += partner
        d += 1
    return total == num
